package app.thetahatch.navi;
import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;
import org.robolectric.*;import org.robolectric.annotation.GraphicsMode;import org.robolectric.annotation.Config;
import android.content.Intent;import android.graphics.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=33) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class AppTest {
 @Test public void carTemplateHasOnlyRequestedActions(){NaviApp a=(NaviApp)RuntimeEnvironment.getApplication();androidx.car.app.testing.TestCarContext c=androidx.car.app.testing.TestCarContext.createCarContext(a);c.updateHandshakeInfo(new androidx.car.app.HandshakeInfo("test.host",2));NaviScreen screen=new NaviScreen(c,a);
  for(String mode:new String[]{"map_only","minimal","full"}){a.variant=mode;androidx.car.app.navigation.model.NavigationTemplate t=(androidx.car.app.navigation.model.NavigationTemplate)screen.onGetTemplate();assertEquals(mode.equals("map_only")?2:mode.equals("minimal")?1:3,t.getMapActionStrip().getActions().size());assertEquals(1,t.getActionStrip().getActions().size());}
  screen.onScroll(100,-40);screen.onScale(0,0,2);assertEquals(1,a.carScroll);assertEquals(1,a.carScale);assertNull(a.maps.car);
 }
 @Test public void tabletClosesWithoutChangingCarState(){try(var ctl=Robolectric.buildActivity(MainActivity.class).setup()){NaviApp a=(NaviApp)ctl.get().getApplication();CameraState c=new CameraState(35,139,17,60,35);a.cameras.changed(true,c);a.command("test","open_tablet",1,0,"");a.command("test","close_tablet",1,0,"");assertTrue(a.cameras.car.near(c));assertFalse(a.tabletOpen);assertEquals(0,a.carGeneration);}}
 @Test public void noKeyDoesNotPretendMapIsLoaded()throws Exception{NaviApp a=(NaviApp)RuntimeEnvironment.getApplication();assertFalse(a.configureSdk());assertFalse(a.state().getBoolean("car_map_loaded"));assertFalse(a.navigatorReady);try{a.command("test","zoom",2,0,"");fail();}catch(IllegalStateException expected){}}
 @Test public void receiverRequiresTestMode(){NaviApp a=(NaviApp)RuntimeEnvironment.getApplication();a.registerReceiver(new TestReceiver(),new android.content.IntentFilter("theta.test.ordered"),android.content.Context.RECEIVER_NOT_EXPORTED);Intent i=new Intent("theta.test.ordered").setPackage(a.getPackageName()).putExtra("cmd","link").putExtra("a","1");a.testMode=false;assertEquals(403,dispatch(a,i));assertFalse(a.cameras.linked);a.testMode=true;assertEquals(0,dispatch(a,i));assertTrue(a.cameras.linked);}
 private int dispatch(NaviApp a,Intent i){int[] r={-99};a.sendOrderedBroadcast(i,null,new android.content.BroadcastReceiver(){public void onReceive(android.content.Context c,Intent intent){r[0]=getResultCode();}},null,-99,null,null);Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();return r[0];}
 @Test public void renderSetupScreen()throws Exception{try(var ctl=Robolectric.buildActivity(MainActivity.class).setup()){android.view.View v=ctl.get().getWindow().getDecorView();v.measure(android.view.View.MeasureSpec.makeMeasureSpec(1440,1073741824),android.view.View.MeasureSpec.makeMeasureSpec(900,1073741824));v.layout(0,0,1440,900);Bitmap b=Bitmap.createBitmap(1440,900,Bitmap.Config.ARGB_8888);v.draw(new Canvas(b));new java.io.File("build/previews").mkdirs();try(var out=new java.io.FileOutputStream("build/previews/setup.png")){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}}
}
